582     def _calculate_agreement(self) -> float:
583         """Calculate inter-annotator agreement score."""
584         if len(self.annotators) < 2:
585             return 1.0
586         
587         # Group annotations by pair
588         pair_annotations = {}
589         for ann in self.annotations:
590             if ann.pair_id not in pair_annotations:
591                 pair_annotations[ann.pair_id] = []
592             pair_annotations[ann.pair_id].append(ann)
593         
594         # Calculate agreement for pairs with multiple annotations
595         agreements = []
596         for pair_id, anns in pair_annotations.items():
597             if len(anns) >= 2:
598                 # Simple agreement: all annotators chose the same option
599                 choices = [ann.choice for ann in anns]
600                 if len(set(choices)) == 1:
601                     agreements.append(1.0)
602                 else:
603                     agreements.append(0.0)
604         
605         return sum(agreements) / len(agreements) if agreements else 0.0
